using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using D=System.Collections.Generic.Dictionary<string,object>;
namespace OreumMok {partial class MainForm {
internal void ValidateComparison(string dir){if(!dir.Contains("qa-native"))throw new Exception("Isolated QA required");var loaded=b.Call("load");var data=J.Obj(loaded["state"]);string qid=Guid.NewGuid().ToString(),pid=Guid.NewGuid().ToString();var quotes=J.Rows(data,"quotes");quotes.Add(J.Row("id",qid,"name","QA price comparison","margin",30,"items",new[]{J.Row("qty",2,"cost",350000)}));data["quotes"]=quotes.ToArray();var prices=J.Rows(data,"competitorPrices");prices.Add(J.Row("id",pid,"name","QA competitor","title","QA only","scope","전체 계단 시공","priceType","단가","unit","단","rate",300000,"quantity",3,"taxMode","별도","vatRate",10,"date",DateTime.Today.ToString("yyyy-MM-dd"),"proof","공개자료 확인","sourceUrl","https://example.com/qa-price","led","제외","demolition","제외","transport","포함","status","사용중"));data["competitorPrices"]=prices.ToArray();b.Call("save",J.Row("state",data,"version",loaded["version"]));LoadState();ShowPage("competitorPrices");Application.DoEvents();var all=FindControls(content).ToList();var own=all.OfType<ComboBox>().First();own.SelectedIndex=own.Items.IndexOf("QA price comparison");all.OfType<NumericUpDown>().First().Value=3;all.OfType<CheckBox>().First().Checked=true;var grid=all.OfType<DataGridView>().First();foreach(DataGridViewRow row in grid.Rows)if(J.Text(row.Tag as D,"id")==pid)grid.CurrentCell=row.Cells[0];all.OfType<Button>().First(x=>x.Text=="견적과 비교").PerformClick();string result=all.OfType<TextBox>().First(x=>x.ReadOnly).Text;if(!result.Contains("110,000")||!result.Contains("200,000")||!result.Contains("동일 조건"))throw new Exception("Native price comparison failed: "+result);using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(Path.Combine(dir,"native-price-comparison.png"));}File.WriteAllText(Path.Combine(dir,"price-comparison-test.json"),"{\"nativeComparison\":true,\"vatNormalized\":true,\"difference\":110000,\"priceMatchProfit\":200000}");}
}
static class ConnectionValidation{internal static void Run(string dir){for(int i=0;i<2;i++){DialogResult expected=i==0?DialogResult.Yes:DialogResult.No;using(var timer=new Timer{Interval=120}){timer.Tick+=(s,e)=>{Form f=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x.Text=="오름목 · 연결 방식");if(f==null)return;timer.Stop();using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(0,0,f.Width,f.Height));image.Save(Path.Combine(dir,expected==DialogResult.Yes?"native-cloud-choice.png":"native-local-choice.png"));}var buttons=f.Controls.Cast<Control>().SelectMany(x=>x.Controls.Cast<Control>()).OfType<Button>();buttons.First(x=>expected==DialogResult.Yes?x.Text.StartsWith("클라우드"):x.Text.StartsWith("이 PC")).PerformClick();};timer.Start();if(StartupMode.Choose()!=expected)throw new Exception("Connection mode selection failed");}}File.WriteAllText(Path.Combine(dir,"connection-mode-test.json"),"{\"cloudChoice\":true,\"localChoice\":true}");}}
}
